// Summe der obersten n Treffer (Stapel vom Inhaltstyp Ganzzahl);
// liegen weniger als n Treffer im Stapel, werden alle addiert.
// Der Stapel darf dabei geleert werden.
public static int schadenOben(Stack treffer, int n) {
    int summe = 0;
    for (int i = 0; i < n; i++) {
        summe = summe + (Integer) treffer.pop();
    }
    return summe;
}

