}

public static Monster staerkstes(Queue q) {
    Monster bestes = null;
    Queue hilf = new Queue();
    while (!q.isEmpty()) {
        Monster m = (Monster) q.dequeue();
        if (bestes == null || m.getStaerke() > bestes.getStaerke()) {
            bestes = m;
        }
        hilf.enqueue(m);
    }
    while (!hilf.isEmpty()) {
        q.enqueue(hilf.dequeue());
    }
    return bestes;
}

