public static int einKind(BinTree b) {
    if (b.isEmpty()) {
        return 0;
    }
    int zaehler = 0;
    if (b.getLeft().isEmpty()
            != b.getRight().isEmpty()) {
        zaehler = 1;
    }
    einKind(b.getLeft());
    einKind(b.getRight());
    return zaehler;
}

