public static int einKind(BinTree b) {
    if (b.isEmpty()) {
        return 0;
    }
    int anzahl = einKind(b.getLeft()) + einKind(b.getRight());
    boolean linksLeer = b.getLeft().isEmpty();
    boolean rechtsLeer = b.getRight().isEmpty();
    if ((linksLeer && !rechtsLeer) || (!linksLeer && rechtsLeer)) {
        anzahl = anzahl + 1;
    }
    return anzahl;
}

