public static int fallenRingsum(char[][] karte, int z, int s) {
    int anzahl = 0;
    for (int dz = -1; dz <= 1; dz++) {
        for (int ds = -1; ds <= 1; ds++) {
            if (karte[z + dz][s + ds] == '^') {
                anzahl++;
            }
        }
    }
    return anzahl;
}

